ALTER TABLE "node_attempts" ADD CONSTRAINT "node_attempts_action_resume_check" CHECK ("node_attempts"."action_resume" IS NULL OR (jsonb_typeof("node_attempts"."action_resume") = 'object' AND "node_attempts"."action_resume"->'version' = '1'::jsonb AND "node_attempts"."action_resume"->>'kind' = 'orchestrator' AND jsonb_typeof("node_attempts"."action_resume"->'sourceCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceAssignmentId') = 'string' AND "node_attempts"."action_resume"->>'assignmentId' = "node_attempts"."execution_assignment_id" AND "node_attempts"."action_resume"->'promptOrdinal' = to_jsonb("node_attempts"."action_prompt_ordinal") AND jsonb_typeof("node_attempts"."action_resume"->'resumeSessionId') = 'string') IS TRUE);